// Fetch RSS sources via node:http(s) natif (sandbox n8n n'expose pas fetch global).
// Parse, filter 24h, dedupe, build OpenClaw payload.

const http = require('node:http');
const https = require('node:https');
const { URL } = require('node:url');

const RSSHUB = 'http://kisnlab-rsshub:1200';
const WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_ITEMS = 60;
const FETCH_TIMEOUT_MS = 10000;
const MAX_REDIRECTS = 3;

const xHandles = [
  'karpathy', 'simonw', 'swyx', 'ylecun', 'fchollet',
  'AnthropicAI', 'darioamodei', 'sama', 'clementdelangue', '_akhaliq',
  'hwchase17', 'goodfellow_ian', 'AlphaSignalAI', 'llama_index', 'le_perceptron'
];

const sources = [
  { url: `${RSSHUB}/anthropic/news`, category: 'ia', source: 'Anthropic News' },
  { url: `${RSSHUB}/openai/blog`, category: 'ia', source: 'OpenAI Blog' },
  { url: 'https://huggingface.co/blog/feed.xml', category: 'ia', source: 'Hugging Face' },
  { url: 'https://www.deeplearning.ai/the-batch/feed/', category: 'ia', source: 'The Batch' },
  { url: 'https://www.latent.space/feed', category: 'ia', source: 'Latent Space' },
  { url: 'https://hnrss.org/frontpage', category: 'dev', source: 'Hacker News' },
  { url: 'https://dev.to/feed', category: 'dev', source: 'DEV.to' },
  { url: `${RSSHUB}/github/trending/daily/any`, category: 'dev', source: 'GitHub Trending' },
  { url: 'https://feeds.feedburner.com/symfony/blog', category: 'dev', source: 'Symfony Blog' },
  { url: 'https://nextjs.org/feed.xml', category: 'dev', source: 'Next.js Blog' },
  { url: 'https://bun.sh/blog/feed.xml', category: 'dev', source: 'Bun Blog' },
  { url: 'https://www.maddyness.com/feed/', category: 'business', source: 'Maddyness' },
  { url: 'https://www.frenchweb.fr/feed', category: 'business', source: 'Frenchweb' },
  { url: 'https://www.bfmtv.com/rss/tech/', category: 'business', source: 'BFM Tech' },
  { url: 'https://feeds.feedburner.com/TheHackersNews', category: 'secu', source: 'The Hacker News' },
  { url: 'https://krebsonsecurity.com/feed/', category: 'secu', source: 'Krebs on Security' },
  { url: 'https://www.cert.ssi.gouv.fr/feed/', category: 'secu', source: 'ANSSI / CERT-FR' },
  ...xHandles.map(h => ({ url: `${RSSHUB}/twitter/user/${h}`, category: 'x', source: `@${h}` }))
];

function fetchOnce(urlStr, timeoutMs) {
  return new Promise((resolve, reject) => {
    let u;
    try { u = new URL(urlStr); } catch (e) { return reject(e); }
    const lib = u.protocol === 'https:' ? https : http;
    const req = lib.request(u, {
      method: 'GET',
      headers: {
        'User-Agent': 'KisnLab-Veille/1.0',
        'Accept': 'application/rss+xml, application/atom+xml, application/xml, text/xml, */*',
        'Accept-Encoding': 'identity'
      },
      timeout: timeoutMs
    }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve({
        status: res.statusCode,
        headers: res.headers,
        text: Buffer.concat(chunks).toString('utf8')
      }));
    });
    req.on('timeout', () => { req.destroy(new Error('timeout')); });
    req.on('error', reject);
    req.end();
  });
}

async function fetchUrl(url, timeoutMs) {
  let current = url;
  for (let i = 0; i <= MAX_REDIRECTS; i++) {
    const r = await fetchOnce(current, timeoutMs);
    if (r.status >= 300 && r.status < 400 && r.headers.location && i < MAX_REDIRECTS) {
      current = new URL(r.headers.location, current).toString();
      continue;
    }
    return r;
  }
  return { status: 0, text: '', headers: {} };
}

function stripCdata(s) {
  return (s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1');
}
function stripTags(s) {
  return stripCdata(s).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}
function firstMatch(re, s) {
  const m = s.match(re);
  return m ? m[m.length - 1] : '';
}
function parseFeed(xml) {
  const items = [];
  const blockRe = /<(item|entry)\b[^>]*>([\s\S]*?)<\/\1>/gi;
  let m;
  while ((m = blockRe.exec(xml)) !== null) {
    const block = m[2];
    const title = stripTags(firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i, block));
    let link = firstMatch(/<link[^>]*href="([^"]+)"/i, block);
    if (!link) link = stripTags(firstMatch(/<link[^>]*>([\s\S]*?)<\/link>/i, block));
    if (!link) link = stripTags(firstMatch(/<guid[^>]*>([\s\S]*?)<\/guid>/i, block));
    const pubDate = firstMatch(/<(pubDate|published|updated|dc:date)[^>]*>([\s\S]*?)<\/\1>/i, block).trim();
    const summary = stripTags(firstMatch(/<(description|summary|content[^>]*)\s*>([\s\S]*?)<\/\1>/i, block)).slice(0, 400);
    if (title && link) items.push({ title: title.slice(0, 200), url: link.trim(), pubDate, summary });
  }
  return items;
}

const diag = [];

async function fetchSource(src) {
  try {
    const r = await fetchUrl(src.url, FETCH_TIMEOUT_MS);
    if (r.status < 200 || r.status >= 300) {
      diag.push(`${src.source}: HTTP ${r.status}`);
      return [];
    }
    const parsed = parseFeed(r.text);
    diag.push(`${src.source}: ${parsed.length} items bruts`);
    return parsed.map(it => ({ ...it, category: src.category, source: src.source }));
  } catch (e) {
    diag.push(`${src.source}: ERR ${e.code || e.name} ${e.message}`);
    return [];
  }
}

const cutoffMs = Date.now() - WINDOW_MS;
const seen = new Set();
const all = [];

const results = await Promise.all(sources.map(fetchSource));
for (const list of results) {
  for (const it of list) {
    if (!it.url || seen.has(it.url)) continue;
    const ts = it.pubDate ? new Date(it.pubDate).getTime() : NaN;
    if (isFinite(ts) && ts < cutoffMs) continue;
    seen.add(it.url);
    all.push(it);
  }
}

all.sort((a, b) => new Date(b.pubDate || 0) - new Date(a.pubDate || 0));
const items = all.slice(0, MAX_ITEMS);

const today = new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });

const goal = [
  `Skill: strategie-veille`,
  `Date: ${today}`,
  `Mode: passif (items ci-dessous déjà fetchés sur les dernières 24h, ne refetch rien).`,
  `Action: synthétise un digest éditorial narratif (4 sections IA / Dev / Business-FR / Sécu, 3-5 phrases prose chacune, liens inline obligatoires, ton Kael, clôture en 1 phrase) selon la spec du skill, puis poste dans #strategie via le bot.`,
  `Si une catégorie n'a aucun item exploitable, écris "RAS aujourd'hui" pour cette section.`,
  ``,
  `Items (${items.length} entrées) :`,
  JSON.stringify(items)
].join('\n');

return [{
  json: {
    action: 'create_flow',
    goal,
    _itemCount: items.length,
    _date: today,
    _diag: diag
  }
}];
